<?php use App\Core\Csrf;use App\Core\Env;use App\Core\View;$base=rtrim(Env::get('APP_URL',''),'/');?>
<div class="page-head"><div><a class="muted" href="<?= View::e($base) ?>/notifications/health">← Salud y recuperación</a><h1>Recuperar entregas fallidas</h1><p>Mercado Libre conserva aquí únicamente eventos no entregados de los últimos dos días. No sustituye la auditoría ni es un historial completo.</p></div></div>
<section class="panel filter-bar"><form method="post" action="<?= View::e($base) ?>/notifications/missed/run" class="form-grid"><input type="hidden" name="_token" value="<?= Csrf::token() ?>"><div class="field"><label>Cuenta para token</label><select class="input" name="account_id"><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>"><?= View::e($a['account_name']) ?></option><?php endforeach;?></select></div><div class="field"><label>Topic opcional</label><select class="input" name="topic"><option value="">Todos permitidos</option><?php foreach(['orders','orders_v2','post_purchase','questions'] as $t):?><option value="<?= $t ?>"><?= $t ?></option><?php endforeach;?></select></div><div class="field"><label>Límite</label><input class="input" type="number" name="limit" min="1" max="50" value="20"></div><div class="field"><label>&nbsp;</label><button class="btn primary">Recuperar manualmente</button></div></form></section>
<section class="panel table-panel"><header class="panel-head"><h2>Últimas recuperaciones</h2></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Fecha</th><th>Topic</th><th>Estado</th><th>Traídas</th><th>Insertadas</th><th>Duplicadas</th><th>Error</th></tr></thead><tbody><?php if(!$runs):?><tr><td colspan="7"><div class="empty">No hay ejecuciones.</div></td></tr><?php endif;?><?php foreach($runs as $r):?><tr><td><?= View::e($r['created_at']) ?></td><td><?= View::e($r['topic']?:'—') ?></td><td><span class="badge <?= $r['status']==='error'?'red':'green' ?>"><?= View::e($r['status']) ?></span></td><td><?= (int)$r['fetched_count'] ?></td><td><?= (int)$r['inserted_count'] ?></td><td><?= (int)$r['duplicate_count'] ?></td><td><?= View::e($r['error_message']?:'—') ?></td></tr><?php endforeach;?></tbody></table></div></section>
